# FILE: rl_config.py

"""
Configuration for the Reinforcement Learning (RL) agent and environment.
"""
from datetime import datetime, timezone
import numpy as np

# --- Environment Configuration ---
# Select which historical data split to use for training/evaluation
# (Matches keys in historical_data_sets generated by ga_optimizer.py or similar loader)
DATA_SET_KEY_TRAIN = 'train'
DATA_SET_KEY_EVAL = 'validation' # Used for evaluating during training

# Initial capital for RL environment simulations
RL_INITIAL_CAPITAL = 10.0 # In SOL (can be same as BACKTEST_INITIAL_CAPITAL)

# Max steps per episode (to prevent infinitely long episodes)
# Adjust based on typical data length per token
MAX_STEPS_PER_EPISODE = 2000 # e.g., ~5.5 hours if 10s steps

# --- Observation Space Configuration ---
# Define the features included in the agent's observation
# This needs careful consideration and normalization
# Example features (adjust as needed):
# - Normalized price change (e.g., last 1, 5, 10 steps)
# - Normalized volatility
# - Normalized market cap
# - Normalized volume
# - RugCheck score (normalized?)
# - Socials score (normalized?)
# - Time since token creation (normalized?)
# - Holding status (0 or 1)
# - PnL of current position (normalized?)
# - Time steps held (normalized?)
# - Normalized SOL balance
OBSERVATION_FEATURES = [
    'price_change_1', 'price_change_5', 'price_change_10', # Normalized log returns or % change
    'volatility', # Normalized
    'market_cap', # Normalized log(market_cap) ?
    'volume', # Normalized log(volume) ?
    'rugcheck_score', # Normalized (e.g., score / 1000)
    'socials_score', # Normalized (e.g., score / 100)
    'time_since_creation_norm', # e.g., log(time_in_seconds + 1) normalized
    'is_holding', # 0 or 1
    'position_pnl_norm', # Normalized PnL if holding, 0 otherwise
    'steps_holding_norm', # Normalized count if holding, 0 otherwise
    'sol_balance_norm' # Normalized
]
# Number of features defined above
OBSERVATION_SPACE_DIM = len(OBSERVATION_FEATURES)

# Define bounds for the observation space (typically [-1, 1] or [0, 1] after normalization)
# Use np.inf for features where bounds aren't strictly fixed after normalization,
# although tighter bounds are generally better.
OBSERVATION_LOW = -1.0 # Example if using -1 to 1 normalization
OBSERVATION_HIGH = 1.0 # Example if using -1 to 1 normalization

# --- Action Space Configuration (Parameter Tuning) ---
# Define which parameters the RL agent will tune. These *must* match
# the parameters expected by the TradingManager/Backtester logic.
# IMPORTANT: Keep this list relatively small initially!
RL_TUNABLE_PARAMETERS = [
    # Name in config, low bound, high bound, type
    ('INITIAL_STOP_LOSS_PERCENT', 5.0, 95.0, float),
    ('FIRST_SELL_PERCENT', 25.0, 100.0, float),
    ('TRAILING_STOP_LOSS_PERCENT', 5.0, 95.0, float),
    ('FIRST_SELL_PROFIT_MARGIN', 10.0, 300.0, float),
    #('SOL_TO_BUY', 0.1, 1.0, float), # Can add later
    # Add more parameters cautiously
]
ACTION_SPACE_DIM = len(RL_TUNABLE_PARAMETERS)

# Action space bounds (min/max for each parameter)
# Must be derived from RL_TUNABLE_PARAMETERS
ACTION_LOW = np.array([p[1] for p in RL_TUNABLE_PARAMETERS], dtype=np.float32)
ACTION_HIGH = np.array([p[2] for p in RL_TUNABLE_PARAMETERS], dtype=np.float32)


# --- Reward Function Configuration ---
# Weights for different reward components (adjust based on priorities)
REWARD_PNL_MULTIPLIER = 1.0          # Reward based on realized PnL
REWARD_SHAPING_UNREALIZED_PNL = 0.01 # Small reward/penalty for change in unrealized PnL
REWARD_SHAPING_HOLDING_PENALTY = -0.001 # Small penalty per step for holding
REWARD_SL_HIT_PENALTY = -0.5        # Penalty for hitting stop loss
REWARD_TP_HIT_BONUS = 0.2           # Bonus for hitting take profit (first or second)


# --- RL Agent & Training Configuration ---
# Choose the RL algorithm (from Stable Baselines3 zoo)
# PPO is generally robust. SAC/TD3 are good alternatives for continuous actions.
RL_ALGORITHM = "PPO" # "PPO", "SAC", "TD3"

# Policy network type
POLICY_KWARGS = dict(net_arch=dict(pi=[64, 64], vf=[64, 64])) # Example: 2 hidden layers of 64 units for both actor and critic

# Training Timesteps (adjust significantly based on performance)
TOTAL_TIMESTEPS = 1_000_000 # Start with 1M, likely needs much more (10M+ ?)

# Number of parallel environments for training (if using SubprocVecEnv)
# Requires sufficient CPU cores
N_ENVS = 4 # Set to 1 if using DummyVecEnv or having issues

# Log directory for TensorBoard
TENSORBOARD_LOG_DIR = "./rl_tensorboard_logs/"

# Directory to save trained models and evaluations
MODEL_SAVE_DIR = "./rl_trained_models/"

# Frequency for evaluating the agent on the validation set (in training steps)
EVAL_FREQ = 20000 # Evaluate every N training steps

# Number of episodes to run for each evaluation
N_EVAL_EPISODES = 10

# --- Data Settings (Ensure consistency with ga_config if reusing data loading) ---
# These might be redundant if loading pre-split data, but good for clarity
DATA_SPLIT_RL = {
    "training": 0.7,    # Larger training set often beneficial for RL
    "validation": 0.15,
    "test": 0.15
}
# Use the same overall date range as GA or define separately
RL_HISTORICAL_DATA_START_TS = datetime(2025, 4, 19, 0, 0, 0, tzinfo=timezone.utc)
RL_HISTORICAL_DATA_END_TS   = datetime(2025, 4, 19, 23, 59, 59, tzinfo=timezone.utc)

# --- Live Agent Configuration ---
# How often the live bot should query the agent for new parameters (in seconds)
AGENT_ACTION_INTERVAL_SECONDS = 60 # e.g., update parameters every minute